/* ========== 微信視頻風（清爽綠 · 大畫面）==========
   幾乎只靠變數改，示範「不寫選擇器也能換皮」 */
:root {
    --vc-accent: #fa5151;          /* 掛斷紅 */
    --vc-answer-color: #07c160;    /* 接聽綠（來電界面） */
    --vc-btn-bg: rgba(255, 255, 255, 0.22);
    --vc-btn-size: 58px;
    --vc-end-btn-size: 64px;
    --vc-name-size: 26px;
    --vc-text-size: 16px;
    --vc-bg-blur: 0px;             /* 對方畫面清晰不糊 */
    --vc-bg-brightness: 0.92;
    --vc-bg-scale: 1.02;
    --vc-incoming-name-size: 30px;
}

/* 台詞改成底部半透明條，貼近微信字幕感 */
.galgame-text-content {
    background: rgba(0, 0, 0, 0.42) !important;
    border-radius: 12px !important;
    padding: 10px 14px !important;
    letter-spacing: 0 !important;
}
.galgame-name-tag { color: #07c160 !important; }

/* 自拍小窗：右上小圓角 */
.camera-preview {
    top: calc(var(--nuo-safe-top, 0px) + 14px) !important;
    right: 14px !important;
    width: 92px !important;
    height: 132px !important;
    border-radius: 10px !important;
}

/* 控制欄：純底色不加漸層，微信式扁平 */
.video-call-controls {
    background: linear-gradient(to top, rgba(0,0,0,0.55) 0%, transparent 70%) !important;
}
.control-label { opacity: 0.85 !important; }

/* 響鈴時畫面壓暗，接通恢復 */
.is-ringing .video-call-bg-image { filter: brightness(0.6) !important; }

