:root {
  --redpacket-icon-top: 5px;
  --redpacket-icon-left: 1px;
  --redpacket-text-size: 15px;
  --redpacket-text-weight: 600;

  --redpacket-text-x: 0px;
  --redpacket-text-y: -13px;
