  color: transparent !important;
}
.msg-redpacket-emoji::before {
  content: "";
  display: block;
  width: 65px !important; 
  height: 70px !important;
  background-image: url('https://nos.netease.com/vcloud-statistic/nrtc/502c92ad-2fb3-4986-ad5a-c258cb0c15ce.png');
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  position: absolute !important;
  top: var(--redpacket-icon-top) !important;
  left: var(--redpacket-icon-left) !important;
  z-index: 5 !important;
